{"code":"const searchResult = await callTool('search_flights', {from: 'BLR', to: 'SYD', maxPrice: 40000});
if (!searchResult || !searchResult.flights || searchResult.flights.length === 0) {
  return {options: [], message: 'No flights found under the price limit.', sampleData: true};
}
const flights = searchResult.flights;
// Get baggage for each flight
const baggagePromises = flights.map(f => callTool('get_baggage_policy', {flightId: f.id}));
const baggageResults = await Promise.all(baggagePromises);
// Combine data
const combined = flights.map((f, idx) => {
  const b = baggageResults[idx];
  return {
    id: f.id,
    airline: f.airline,
    price: f.price,
    checkedKg: b ? b.checkedKg : null
  };
});
// Filter by checkedKg >= 20 and price already under maxPrice
const filtered = combined.filter(c => c.checkedKg !== null && c.checkedKg >= 20);
// Sort by price ascending (should already be sorted but ensure)
filtered.sort((a, b) => a.price - b.price);
const top3 = filtered.slice(0, 3);
return {options: top3, sampleData: true, message: `Found ${top3.length} flights meeting criteria.`};"}

